// B2: verify every rule of the simplify and fold tables once, with the full methods (1e6 random assignments,
// exhaustive 2^32 where a rule has one full variable and no proof), and record the evidence:
//   src/typed/rules/evidence.ts           the table rules' evidence, keyed by rule name (generated; do not edit)
//   various/08-rule-evidence.json         everything, including the candidate rules
//   node scripts/04-verify-rules.mjs [--random N] [--no-exhaustive]
import { writeFileSync } from 'node:fs';
const root = new URL('../../../../../../', import.meta.url).pathname;
const ticket = new URL('../', import.meta.url).pathname;
const { verifyRule } = await import(root + 'dist/typed/rules/verify.js');
const { SIMPLIFY_RULES } = await import(root + 'dist/typed/rules/simplify.js');
const { FOLD_RULES } = await import(root + 'dist/typed/rules/fold.js');
const C = await import(root + 'dist/typed/rules/candidates.js');

const args = process.argv.slice(2);
const random = args.includes('--random') ? +args[args.indexOf('--random') + 1] : 1e6;
const exhaustive32 = !args.includes('--no-exhaustive');
const opts = { random, seed: 7, exhaustive32 };
const sets = [SIMPLIFY_RULES, FOLD_RULES, C.UNSOUND_CANDIDATES, C.F32_SOUND_CANDIDATES];
const all = {}, table = {};
const t0 = performance.now();
for (const set of sets) {
  all[set.name] = {};
  for (const r of set.rules) {
    const t = performance.now();
    const e = verifyRule(r, opts);
    all[set.name][r.name] = e;
    if (set === SIMPLIFY_RULES || set === FOLD_RULES) table[r.name] = e;
    const m = e.methods.filter(x => x.verdict !== 'n/a').map(x => x.method).join(',');
    console.log(
      `${set.name.padEnd(18)} ${r.name.padEnd(16)} ${e.verdict.padEnd(8)} ${(e.strength ?? '-').padEnd(23)} ${String(Math.round(performance.now() - t)).padStart(7)} ms  ${m}${e.counterexample ? '  ' + JSON.stringify(e.counterexample) : ''}${e.reason ? '  ' + e.reason : ''}`,
    );
  }
}
const ms = Math.round(performance.now() - t0);
const meta = { generatedBy: 'ttmp/2026/11/25/IRWB-006--…/scripts/04-verify-rules.mjs', options: opts, ms };
writeFileSync(ticket + 'various/08-rule-evidence.json', JSON.stringify({ meta, evidence: all }, null, 1));
const src = `/**
 * Recorded verification evidence for every rule of the simplify and fold tables (IRWB-006, B2), keyed by rule name.
 * Generated by ${meta.generatedBy} with ${JSON.stringify(opts)} in ${ms} ms; do not edit by hand. Each record names
 * the rule's version and the fingerprint (SHA-256 of its canonical data) it was computed for; a test fails when a
 * rule no longer matches its record, so an edited rule must be verified again.
 */
import type { RuleEvidence } from './verify.js';

export const EVIDENCE_OPTIONS = ${JSON.stringify(opts)} as const;
export const RULE_EVIDENCE: Readonly<Record<string, RuleEvidence>> = ${JSON.stringify(table, null, 2)};
`;
writeFileSync(root + 'src/typed/rules/evidence.ts', src);
console.log(JSON.stringify({ rules: Object.keys(table).length, ms }));
